/**
 * Build script for dsh-whale-pet.
 * Compiles TypeScript source to lib/ and bundles the client artifact
 * matching DSH Client Module specifications.
 * Inlines character PNGs as base64 Data URIs to eliminate 404s in DSH Desktop & Web.
 */

import { readFileSync, writeFileSync, mkdirSync, existsSync, renameSync } from 'node:fs'
import { join, dirname } from 'node:path'
import { fileURLToPath } from 'node:url'
import { createHash } from 'node:crypto'
import ts from 'typescript'

const __dirname = dirname(fileURLToPath(import.meta.url))

const srcAssetsDir = join(__dirname, 'assets')

// Pose constant name -> asset file stem (assets/<stem>.png). Order is irrelevant; names must stay unique.
const POSE_ASSETS = [
  ['MAID', 'Maid'], ['CHIBI', 'DaFeiYu'], ['ANSWERING', 'Answering'], ['BAIFAN', 'baifan'],
  ['GETIT', 'getit'], ['SAJIAO', 'sajiao'], ['THINK1', 'Think1'], ['THINK2', 'Think2'],
  ['THINK3', 'Think3'], ['THINK4', 'Think4'], ['THINK5', 'Think5'], ['DIZZY', 'Dizzy'],
  ['SMUG', 'smug'], ['SHY', 'shy'], ['ANGRY', 'angry'], ['SURPRISED', 'surprised'],
  ['PROUD', 'proud'], ['HAPPY', 'happy'], ['CARRY', 'carry'], ['PEEK', 'peek'],
]

console.log('[build] 1. Generating src/client/assets-data.ts with embedded image Data URIs...')
// Prefer the compact WebP (scripts/optimize-assets.py) while it was made from the current PNG.
const optimizedDir = join(srcAssetsDir, 'optimized')
const manifestPath = join(optimizedDir, 'manifest.json')
const optimizedManifest = existsSync(manifestPath) ? JSON.parse(readFileSync(manifestPath, 'utf-8')) : {}
let embeddedBytes = 0
const poseDataUris = Object.fromEntries(POSE_ASSETS.map(([constant, stem]) => {
  const png = readFileSync(join(srcAssetsDir, stem + '.png'))
  const webpPath = join(optimizedDir, stem + '.webp')
  const fresh = existsSync(webpPath) && optimizedManifest[stem]?.png_sha1 === createHash('sha1').update(png).digest('hex')
  const bytes = fresh ? readFileSync(webpPath) : png
  embeddedBytes += bytes.length
  return [constant, `data:image/${fresh ? 'webp' : 'png'};base64,${bytes.toString('base64')}`]
}))
console.log(`[build]    embedded artwork: ${(embeddedBytes / 1048576).toFixed(1)} MB`)

const assetsDataTs = `/**
 * Embedded character image Data URIs for dsh-whale-pet.
 * Generated by build.js from assets/.
 * Eliminates 404 network errors in DSH desktop & web environments.
 */
${POSE_ASSETS.map(([constant]) => `export const ${constant}_DATA_URI: string = ${JSON.stringify(poseDataUris[constant])}`).join('\n')}
`
const generatedAssetsPath = join(__dirname, 'src', 'client', 'assets-data.ts')
if (!existsSync(generatedAssetsPath) || readFileSync(generatedAssetsPath, 'utf-8') !== assetsDataTs) writeFileSync(generatedAssetsPath, assetsDataTs, 'utf-8')

console.log('[build] 2. Running TypeScript compiler...')
const configPath = join(__dirname, 'tsconfig.json')
const config = ts.readConfigFile(configPath, ts.sys.readFile)
if (config.error) throw new Error(ts.flattenDiagnosticMessageText(config.error.messageText, '\n'))
const parsed = ts.parseJsonConfigFileContent(config.config, ts.sys, __dirname)
const compilerHost = ts.createCompilerHost(parsed.options)
// Avoid rewriting unchanged multi-megabyte embedded assets on every UI edit.
compilerHost.writeFile = (path, contents) => {
  if (existsSync(path) && readFileSync(path, 'utf-8') === contents) return
  mkdirSync(dirname(path), { recursive: true })
  writeFileSync(path, contents, 'utf-8')
}
const program = ts.createProgram(parsed.fileNames, parsed.options, compilerHost)
const diagnostics = [...parsed.errors, ...ts.getPreEmitDiagnostics(program)]
if (diagnostics.some(diagnostic => diagnostic.category === ts.DiagnosticCategory.Error)) {
  throw new Error(ts.formatDiagnosticsWithColorAndContext(diagnostics, {
    getCurrentDirectory: () => __dirname,
    getCanonicalFileName: path => path,
    getNewLine: () => '\n',
  }))
}
const emit = program.emit()
if (emit.emitSkipped) throw new Error('TypeScript emit was skipped')

// Artwork is embedded in lib/client.js; nothing reads image files at runtime, so none are copied into lib/.
console.log('[build] 3. Bundling lib/client.js for DSH browser module loader...')
const petOverlayCss = readFileSync(join(__dirname, 'src', 'client', 'PetOverlay.module.css'), 'utf-8')
const galgameCss = readFileSync(join(__dirname, 'src', 'client', 'galgame.css'), 'utf-8')
const puppetCss = readFileSync(join(__dirname, 'src', 'client', 'LivingPuppet.module.css'), 'utf-8')
const fullCss = `${petOverlayCss}\n${galgameCss}\n${puppetCss}`

// Embed compiler output to keep state and host integration identical in both entry points.
const stateMachineSource = readFileSync(join(__dirname, 'lib/client/state-machine.js'), 'utf-8')
  .replace(/^export /gm, '').replace(/^\/\/# sourceMappingURL=.*$/gm, '')
const clientAdapterSource = readFileSync(join(__dirname, 'lib/client/index.js'), 'utf-8')
  .replace(/^import .*$/gm, '').replace(/^export /gm, '')
  .replace(/^\/\/# sourceMappingURL=.*$/gm, '')

// Compile both React views into the template, using the same source as type checking.
function compileView(file, component) {
  const source = readFileSync(join(__dirname, 'src/client', file), 'utf-8').replace(/^import[\s\S]*?from ['"][^'"]+['"]\s*$/gm, '')
  const code = ts.transpileModule(source, { compilerOptions: { target: ts.ScriptTarget.ES2022, module: ts.ModuleKind.ESNext, jsx: ts.JsxEmit.React } }).outputText.replace(/^export /gm, '')
  return 'const ' + component + ' = (() => { const styles = new Proxy({}, { get: (_, key) => key });\n' + code + '\nreturn ' + component + '; })();'
}
// Pure modules: compiler output with imports/exports removed. They share one
// factory scope, so top-level names must be unique across modules.
function moduleSource(file) {
  return readFileSync(join(__dirname, 'lib/client', file), 'utf-8')
    .replace(/^import .*$/gm, '').replace(/^export /gm, '')
    .replace(/^\/\/# sourceMappingURL=.*$/gm, '')
}
const preferencesSource = moduleSource('preferences.js')
const pureModules = ['peek-shortcut.js', 'live2d-loader.js', 'live2d-look.js', 'touch.js', 'carry.js', 'live2d-motion.js', 'live2d-package.js', 'features.js', 'poses.js', 'layout.js', 'wallet.js', 'peak.js', 'account-balance.js', 'voice.js', 'scenes.js', 'media-store.js', 'bgm.js', 'rig.js', 'live-rig.js', 'emotion.js', 'experience.js', 'usability.js', 'hitareas.js']
  .map(moduleSource).join('\n')
// Views are hook-free render functions or components; order matters only for readability.
const views = [
  ['DialogueContent.tsx', 'DialogueContent'],
  ['LivingPuppet.tsx', 'LivingPuppet'],
  ['SettingsPanel.tsx', 'SettingsPanel'],
  ['TheatreView.tsx', 'TheatreView'],
  ['PetOverlay.tsx', 'PetOverlay'],
].map(([file, component]) => compileView(file, component)).join('\n')

// Live2D (optional): Cubism Core from vendor/live2d/Core (downloaded by the maintainer from
// live2d.com, Live2D Proprietary Software License) and the runtime in live2d/ bundled with the
// official Cubism Web Framework. Both are wrapped in functions that run only when an imported
// model is shown (src/client/live2d-loader.ts). The model itself is never part of the build.
console.log('[build] 3a. Bundling Live2D runtime...')
const cubismCorePath = join(__dirname, 'vendor', 'live2d', 'Core', 'live2dcubismcore.min.js')
let live2dSource = ''
if (!existsSync(cubismCorePath)) {
  console.warn('[build]    vendor/live2d/Core/live2dcubismcore.min.js not found: building without Live2D (illustrations only).')
} else {
  const esbuild = await import('esbuild')
  const runtime = await esbuild.build({
    entryPoints: [join(__dirname, 'live2d', 'runtime.ts')], bundle: true, format: 'iife', globalName: 'DSHLive2DRuntime',
    target: 'es2020', minify: true, legalComments: 'inline', write: false, logLevel: 'warning',
    loader: { '.frag': 'text', '.vert': 'text' },
    // Plain strings instead of multi-line template literals: no raw newlines or trailing spaces in lib/client.js.
    supported: { 'template-literal': false },
  })
  // Core probes for CommonJS/AMD; shadow those names so a host AMD loader never sees an anonymous define().
  live2dSource = 'function __dshLoadCubismCore() {\n  var define = void 0, module = void 0, exports = void 0;\n'
    + readFileSync(cubismCorePath, 'utf-8') + '\n  return Live2DCubismCore;\n}\n'
    + 'function __dshLoadLive2DRuntime() {\n' + runtime.outputFiles[0].text + '\n  return DSHLive2DRuntime;\n}\n'
  console.log(`[build]    Live2D runtime: ${(live2dSource.length / 1024).toFixed(0)} KB`)
}

const clientBundleSource = `/**
 * dsh-whale-pet browser client bundle.
 * Self-contained Cordis Web UI client plugin.
 */
(function() {
  if (typeof window === 'undefined' || !window.__ModuleLoader__) {
    return;
  }

  window.__ModuleLoader__.load({
    id: 'dsh-whale-pet',
    factory: function(require) {
      const React = require('react');
      const h = React.createElement;
      const useState = React.useState;
      const useEffect = React.useEffect;
      const useRef = React.useRef;
      const useCallback = React.useCallback;
      const useMemo = React.useMemo;

      // Inject styles into document head on materialization
      let styleEl = document.getElementById('dsh-whale-pet-styles');
      if (!styleEl) {
        styleEl = document.createElement('style');
        styleEl.id = 'dsh-whale-pet-styles';
        styleEl.textContent = ${JSON.stringify(fullCss)};
        document.head.appendChild(styleEl);
      }

      ${stateMachineSource}

${POSE_ASSETS.map(([c]) => `      const ${c}_DATA_URI = ${JSON.stringify(poseDataUris[c])};`).join('\n')}
      ${live2dSource}
      ${preferencesSource}
      ${pureModules}
      ${views}
      ${clientAdapterSource}
      return {
        inject,
        apply(ctx) {
          apply(ctx);
          ctx.effect(() => () => styleEl.remove());
        },
      };
    },
  });
})();
`

const libClientPath = join(__dirname, 'lib', 'client.js')
const bundleTemporaryPath = libClientPath + '.tmp'
writeFileSync(bundleTemporaryPath, clientBundleSource.replace(/^[ \t]+$/gm, ''), 'utf-8')
for (let attempt = 0; ; attempt++) {
  try { renameSync(bundleTemporaryPath, libClientPath); break }
  catch (error) { if (attempt >= 5) throw error; await new Promise(resolve => setTimeout(resolve, 150)) }
}
console.log(`[build] Successfully generated ${libClientPath}`)
